export function chartMaximum(values) {
  return Math.max(1,...values.filter(value=>typeof value==='number'&&Number.isFinite(value)));
}
export function lineSegments(rows,key,{width=480,height=180,maximum}={}) {
  const max=maximum??chartMaximum(rows.map(row=>row[key]));
  const segments=[];let current=[];
  rows.forEach((row,index)=>{
    const value=row[key];
    if(typeof value!=='number'||!Number.isFinite(value)){if(current.length)segments.push(current);current=[];return;}
    const x=rows.length<2?0:index/(rows.length-1)*width;
    const y=height-Math.max(0,value)/max*height;
    current.push({x,y,value,date:row.date??row.week});
  });
  if(current.length)segments.push(current);
  return segments;
}
export function countLabel(value,unit='issues'){return value+' '+(unit==='points'?'points':value===1?'issue':'issues');}

import {chartMaximum,lineSegments,countLabel} from './chart-data.js';
export function BarChart({title,items,valueKey='count',labelKey='name',unit='issues',id='bar-chart'}) {
  const maximum=chartMaximum(items.map(item=>item[valueKey]));
  const height=Math.max(100,items.length*36+30);
  return <section className="chart-panel"><h2 id={id}>{title}</h2>{!items.length?<p>No matching issues.</p>:<>
    <svg viewBox={'0 0 520 '+height} role="img" aria-labelledby={id}>
      {items.map((item,index)=><g key={item.id??item.priority??index} transform={'translate(0 '+(index*36+10)+')'}>
        <text x="0" y="18" fontSize="12">{String(item[labelKey]??'Unassigned').slice(0,21)}</text>
        <rect x="165" y="2" width={item[valueKey]/maximum*290} height="24" fill="#4263c7"><title>{item[labelKey]}: {countLabel(item[valueKey],unit)}</title></rect>
        <text x={175+item[valueKey]/maximum*290} y="19" fontSize="12">{item[valueKey]}</text>
      </g>)}
    </svg><table><thead><tr><th>Group</th><th>{unit==='points'?'Points':'Issues'}</th></tr></thead><tbody>{items.map((item,index)=><tr key={item.id??item.priority??index}><td>{item[labelKey]??'Unassigned'}</td><td>{item[valueKey]}</td></tr>)}</tbody></table>
  </>}</section>;
}
export function LineChart({title,rows,series,id='line-chart',unit='points'}) {
  const maximum=chartMaximum(rows.flatMap(row=>series.map(item=>row[item.key])));
  const width=450,height=180;
  return <section className="chart-panel"><h2 id={id}>{title}</h2>{!rows.length?<p>No reporting history yet.</p>:<>
    <svg viewBox="0 0 530 250" role="img" aria-labelledby={id}>
      <g transform="translate(45 15)">
        {[0,.25,.5,.75,1].map(ratio=><g key={ratio}><line x1="0" x2={width} y1={height-height*ratio} y2={height-height*ratio} stroke="#d6deea"/><text x="-8" y={height-height*ratio+4} textAnchor="end" fontSize="11">{Math.round(maximum*ratio*10)/10}</text></g>)}
        {series.map(item=>lineSegments(rows,item.key,{width,height,maximum}).map((segment,index)=><g key={item.key+index}>
          <polyline fill="none" stroke={item.color} strokeWidth="2.5" strokeDasharray={item.dashed?'5 4':undefined} points={segment.map(point=>point.x+','+point.y).join(' ')}/>
          {segment.map(point=><circle key={point.date} cx={point.x} cy={point.y} r="3" fill={item.color}><title>{point.date}: {item.label} {point.value} {unit}</title></circle>)}
        </g>))}
        <text x="0" y="202" fontSize="11">{rows[0].date??rows[0].week}</text><text x={width} y="202" textAnchor="end" fontSize="11">{rows.at(-1).date??rows.at(-1).week}</text>
      </g>
    </svg><p>{series.map(item=><span key={item.key} style={{color:item.color,marginRight:'1rem'}}>● {item.label}</span>)}</p>
    <details><summary>Show chart data</summary><div className="table-scroll"><table><thead><tr><th>Date</th>{series.map(item=><th key={item.key}>{item.label}</th>)}</tr></thead><tbody>{rows.map(row=><tr key={row.date??row.week}><td>{row.date??row.week}</td>{series.map(item=><td key={item.key}>{row[item.key]===null?'Future':row[item.key]}</td>)}</tr>)}</tbody></table></div></details>
  </>}</section>;
}

import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading,useLoad} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useLiveUpdates} from '../../live.js';
import {LiveControl} from './activity.jsx';
import {BarChart,LineChart} from './charts.jsx';
const priorityNames=['No priority','Urgent','High','Normal','Low'];
export function DashboardPage({api,query,navigate}) {
  const [orgId,setOrgId]=useState(query.orgId??''),[projectId,setProjectId]=useState(query.projectId??'');
  const [weeks,setWeeks]=useState('12'),[date,setDate]=useState(''),[sprintId,setSprintId]=useState('');
  const [unit,setUnit]=useState('issues'),[showIdeal,setShowIdeal]=useState(true),[showScope,setShowScope]=useState(true);
  const orgs=useLoad(()=>api.get('/orgs?limit=200'),[]);
  const projects=useLoad(()=>orgId?api.get('/projects?'+queryString({orgId,archived:'all',limit:200})):Promise.resolve({items:[]}),[orgId]);
  const report=useLoad(()=>orgId?api.get('/dashboard?'+queryString({orgId,projectId,weeks,date,sprintId})):Promise.resolve(null),[orgId,projectId,weeks,date,sprintId]);
  const live=useLiveUpdates({orgId,projectId,enabled:Boolean(orgId),onActivity:()=>report.reload()});
  const data=report.data,valueKey=unit==='points'?'points':'count';
  const burndown=data?.burndown;
  const series=[...(showScope?[{key:'scope',label:'Scope',color:'#8757c4'}]:[]),{key:'remaining',label:'Remaining',color:'#d96031'},...(showIdeal?[{key:'idealRemaining',label:'Ideal',color:'#4263c7',dashed:true}]:[])];
  return <Page title="Dashboard"><form className="insight-filters" onSubmit={event=>{event.preventDefault();report.reload();navigate('/dashboard?'+queryString({orgId,projectId}));}}>
    <Field label="Organization"><select value={orgId} onChange={event=>{setOrgId(event.currentTarget.value);setProjectId('');setSprintId('');}}><option value="">Choose organization</option>{orgs.data?.items.map(org=><option key={org.id} value={org.id}>{org.name}</option>)}</select></Field>
    <Field label="Project"><select value={projectId} onChange={event=>{setProjectId(event.currentTarget.value);setSprintId('');}}><option value="">All accessible projects</option>{projects.data?.items.map(project=><option key={project.id} value={project.id}>{project.key} · {project.name}</option>)}</select></Field>
    <Field label="Reporting weeks" type="number" min="1" max="52" value={weeks} onChange={event=>setWeeks(event.currentTarget.value)}/>
    <Field label="Throughput ending date (UTC)" type="date" value={date} onChange={event=>setDate(event.currentTarget.value)}/>
    <Field label="Chart unit"><select value={unit} onChange={event=>setUnit(event.currentTarget.value)}><option value="issues">Issues</option><option value="points">Estimate points</option></select></Field><Button type="submit">Refresh dashboard</Button>
  </form><Notice error={report.error??orgs.error??projects.error}/>{!orgId?<Empty>Choose an organization to report on its accessible projects.</Empty>:<><LiveControl live={live}/>
    {report.loading?<Loading/>:data&&<>
      <div className="dashboard-grid" aria-label="Issue totals">{[['Total issues',data.totals.issues],['Open',data.totals.open],['Done',data.totals.done],['Unassigned',data.totals.unassigned],['Overdue',data.totals.overdue],['Estimate points',data.totals.points]].map(([label,value])=><article className="chart-panel"><h2>{label}</h2><strong>{value}</strong></article>)}</div>
      <p>Current counts include {data.projects.length} accessible projects. Throughput counts distinct issues completed per UTC week; reopening and completing an issue again in one week counts once. Past count snapshots are not reconstructed.</p>
      <div className="dashboard-grid"><BarChart id="status-chart" title="By workflow status" items={data.byStatus} valueKey={valueKey} unit={unit}/><BarChart id="assignee-chart" title="By assignee" items={data.byAssignee} valueKey={valueKey} unit={unit}/><BarChart id="priority-chart" title="By priority" items={data.byPriority.map(row=>({...row,name:priorityNames[row.priority]}))} valueKey={valueKey} unit={unit}/></div>
      <LineChart id="throughput-chart" title="Weekly throughput" rows={data.throughput} unit={unit} series={[{key:unit==='points'?'points':'issues',label:'Completed',color:'#267d68'}]}/>
      <section><h2>Sprint burndown</h2><Field label="Sprint"><select value={sprintId||burndown?.sprint.id||''} onChange={event=>setSprintId(event.currentTarget.value)}><option value="">Choose sprint</option>{data.sprints.map(sprint=><option key={sprint.id} value={sprint.id}>{sprint.name} · {sprint.status}</option>)}</select></Field>
        <label><input type="checkbox" checked={showIdeal} onChange={event=>setShowIdeal(event.currentTarget.checked)}/> Show ideal line</label><label><input type="checkbox" checked={showScope} onChange={event=>setShowScope(event.currentTarget.checked)}/> Show scope line</label>
        {burndown?<><p>{burndown.sprint.name}: {burndown.changes} recorded scope/progress changes. Future actual values remain blank; missing estimates contribute zero points.</p><LineChart id="burndown-chart" title={burndown.sprint.name+' burndown'} rows={burndown.days} series={series}/></>:<Empty>Create a sprint to see its recorded daily burndown.</Empty>}
      </section>
    </>}
  </>}</Page>;
}
